"""Replace finder presentation; retain the existing data, filter and ranking functions."""
from pathlib import Path
r=Path(__file__).resolve().parents[1];p=r/'js/meal-finder.js';s=p.read_text(encoding='utf-8')
s=s.replace('let state,visible=12,selected=[],saved=[];',"const pageSize=root.hasAttribute('data-home-preview')?4:12;\n  let state,visible=pageSize,selected=[],saved=[];")
