markup="""  root.innerHTML=`<div class="discovery-product"><div class="finder-sidebar filter-deck"><form id="finder-filters"><div class="filter-panel-head"><h2>Make it your meal.</h2><button type="button" data-close-filters>Done</button></div><div class="filter-primary"><fieldset><legend>Nutrition limits</legend>${field('maxCal')}${field('minProtein')}</fieldset><details class="restaurant-picker"><summary><span>Choose restaurants</span><small>One or more</small></summary><div class="restaurant-checks">${choices('chain')}</div></details></div><details class="filter-more"><summary>More preferences <span>Goals, food choices &amp; nutrients</span></summary><div class="filter-expanded"><fieldset><legend>Bring these meals to the top</legend>${choices('goal')}<p class="filter-note">Preferences change the order. Nutrition limits exclude meals.</p></fieldset><fieldset><legend>Food &amp; meal time</legend>${choices('diet')}${choices('meal')}<p class="filter-note">Ingredient preferences are not allergy-safety checks. Ask the restaurant.</p></fieldset><fieldset><legend>Other nutrients</legend>${field('minFiber')}${field('maxSodium')}<label>Preferred size<select name="size"><option value="">Any size</option>${facets.size.map(([v,l])=>'<option value="'+v+'"'+(state.size[0]===v?' selected':'')+'>'+l+'</option>').join('')}</select></label><label class="finder-choice"><input type="checkbox" name="incomplete"${!state.complete?' checked':''}><span>Include incomplete records</span></label></fieldset></div></details><div class="filter-reset"><button type="reset" class="quiet-button">Reset filters</button><p>Unknown values cannot meet a numeric limit.</p></div></form></div><div class="finder-results"><div class="finder-toolbar"><div><p class="section-overline">On your shortlist</p><p class="results-count" role="status" aria-live="polite"></p></div><button type="button" class="filter-launch" data-open-filters>Adjust filters <span data-filter-count></span></button><label class="sort-label">Order by<select name="sort"><option value="match">Preference order</option><option value="calories">Lowest calories</option><option value="protein">Most protein</option></select></label></div><div class="active-preferences" aria-label="Active filters"></div><div class="results-grid"></div><button type="button" class="btn results-more" data-more>Show more meals</button><div class="finder-end"><p>U.S. menu data. Portions, sauces and local recipes may change the numbers. <a href="sources.html">About our data</a></p><button type="button" data-share>Share results</button><p data-share-status role="status"></p></div></div></div><div class="compare-tray" hidden><span data-compare-count></span><button type="button" class="btn btn-primary" data-open-compare>Compare meals</button><button type="button" data-clear-compare>Clear</button></div><dialog class="compare-dialog" aria-labelledby="compare-title"><div class="dialog-heading"><h2 id="compare-title">Your meals, side by side</h2><button type="button" data-close-compare>Close</button></div><div class="comparison-output" tabindex="0" role="region" aria-label="Meal comparison"></div></dialog><dialog class="filter-dialog" aria-label="Meal filters"></dialog>`;
"""
s=s[:a]+markup+s[b:]
a=s.index('  function mealRow(');b=s.index('  function activeFilters()',a)
s=s[:a]+"""  function mealRow(m){
    const id=meals.indexOf(m);
    return `<article class="order-ticket meal-row" data-meal-id="${id}">
      <header class="order-identity"><a href="${esc(m.url)}">${esc(m.chain)}</a><button type="button" data-save="${id}" aria-pressed="${saved.includes(key(m))}">${saved.includes(key(m))?'Saved':'Save meal'}</button></header>
      <div class="order-heading"><h2>${esc(m.name.replace('High-protein bulking order: ',''))}</h2><p>${esc(m.serving||'1 listed order')} · ${esc(m.region||'U.S.')} menu</p></div>
      <dl class="order-nutrition meal-numbers"><div class="order-major"><dt>Calories</dt><dd>${number(m.cal)}</dd></div><div class="order-major"><dt>Protein</dt><dd>${number(m.p,'g')}</dd></div><div><dt>Carbs</dt><dd>${number(m.c,'g')}</dd></div><div><dt>Fat</dt><dd class="${!Number.isFinite(m.fat)?'unknown':''}">${number(m.fat,'g')}</dd></div></dl>
      <div class="order-included"><h3>What's included</h3><p>${esc(m.why)}</p></div>
      <footer class="order-actions"><details><summary>Details &amp; source</summary><p>Fiber: ${number(m.f,'g')} · Sodium: ${number(m.na,'mg')}.</p><p>Per listed order. Extras are separate unless included above. Missing numbers are not zero.</p>${m.source?'<p><a href="'+esc(m.source)+'">Official nutrition source</a> · Record checked '+esc(m.checked)+'</p>':'<p>Source details are unavailable.</p>'}<a href="${esc(m.url)}">Restaurant menu</a></details><label class="compare-choice"><input type="checkbox" data-compare="${id}"${selected.includes(id)?' checked':''}>Compare meal</label></footer>
    </article>`;
  }
"""+s[b:]
s=s.replace("if(matchMedia('(max-width: 800px)').matches)root.querySelector('[data-open-filters]').focus", "root.querySelector('[data-open-filters]').focus")
